int main() {
    int arr[] = {10, 20, 30, 40, 50};
    int *p = arr + 1;
    printf("%d", *(p + 1));
    return 0;
}

#include <stdio.h>
int compute(int n) {
    if (n <= 1) return 1;
    return n + compute(n - 2);
}
int main() {
    printf("%d", compute(2));
    return 0;
}

